import fs from "node:fs"
import path from "node:path"

// Best-effort delete of a file previously served at `/uploads/...`. Every url in the DB was
// generated by this app itself (see config/upload.ts) as `/uploads/<subfolder>/<hex><ext>` — never
// user input — so resolving it straight off process.cwd() is safe, no path-traversal risk.
// Deleting a task/ticket used to only remove the DB rows pointing at these files, silently
// orphaning the actual evidence photos/attachments on disk forever (no retention sweep catches
// this the way it does for audit logs/notifications/inbound messages) — this makes deletion clean
// up after itself instead. A missing file (already gone, or the row's url was never valid) is not
// an error worth failing the parent delete over, so failures are logged and swallowed.
export function unlinkUploadUrl(url: string): void {
    const relative = url.startsWith("/") ? url.slice(1) : url
    const absolute = path.resolve(process.cwd(), relative)
    fs.unlink(absolute, (err) => {
        if (err && err.code !== "ENOENT") console.error(`Failed to delete uploaded file ${url} from disk:`, err)
    })
}

export function unlinkUploadUrls(urls: string[]): void {
    urls.forEach(unlinkUploadUrl)
}
